CREATE DATABASE IF NOT EXISTS neurolaudos CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE neurolaudos;
CREATE TABLE IF NOT EXISTS users(id CHAR(36) PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,name VARCHAR(180) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','psychologist','assistant') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients(id CHAR(36) PRIMARY KEY,name VARCHAR(255) NOT NULL,birth_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluations(id CHAR(36) PRIMARY KEY,patient_id CHAR(36) NOT NULL,created_by CHAR(36) NOT NULL,status ENUM('draft','review','approved') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS documents(id CHAR(36) PRIMARY KEY,evaluation_id CHAR(36) NOT NULL,kind ENUM('base','anamnesis','export') NOT NULL,filename VARCHAR(255) NOT NULL,storage_path VARCHAR(300) NOT NULL,sha256 CHAR(64) NOT NULL,extracted_json LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(evaluation_id) REFERENCES evaluations(id));
CREATE TABLE IF NOT EXISTS sections(id CHAR(36) PRIMARY KEY,evaluation_id CHAR(36) NOT NULL,section_key VARCHAR(100) NOT NULL,title VARCHAR(200) NOT NULL,content LONGTEXT NOT NULL,status ENUM('generated','edited','approved') DEFAULT 'generated',source_summary LONGTEXT,version INT DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_section(evaluation_id,section_key),FOREIGN KEY(evaluation_id) REFERENCES evaluations(id));
CREATE TABLE IF NOT EXISTS section_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,section_id CHAR(36) NOT NULL,version INT NOT NULL,content LONGTEXT NOT NULL,actor_id CHAR(36),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(section_id) REFERENCES sections(id));
CREATE TABLE IF NOT EXISTS prompt_templates(id VARCHAR(100) PRIMARY KEY,name VARCHAR(200) NOT NULL,prompt LONGTEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_settings(id INT PRIMARY KEY,model VARCHAR(120) NOT NULL,enabled BOOLEAN DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO ai_settings(id,model,enabled) VALUES(1,'gpt-4.1',false);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id CHAR(36),evaluation_id CHAR(36),action VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
